/**
 * Version consistency checker
 *
 * package.json is the only place a version is typed by hand. Everything
 * else derives from it:
 *   - the userscript header @version — written by build.js;
 *   - LOCALE_DELIVERY_MANIFEST.version in src/i18n.js — generated by
 *     scripts/sync-locale-metadata.js (the locale tag and cache key derive
 *     from it at runtime);
 *   - the running version — U.getScriptVersion() reads GM_info.
 *
 * This script fails when src/*.js contains a hand-written version literal
 * (version: 'X.Y.Z' / currentVersion: 'X.Y.Z') or when the generated
 * manifest version differs from package.json.
 *
 * Usage: node scripts/check-version-consistency.js
 */
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const srcDir = path.join(root, 'src');

const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
const canonicalVersion = pkg.version;

if (!/^\d+\.\d+\.\d+/.test(canonicalVersion)) {
  console.error(`❌ Invalid version in package.json: "${canonicalVersion}"`);
  process.exit(1);
}

const VERSION_RE = /(?:currentVersion|version)\s*[:=]\s*['"](\d+\.\d+\.\d+)['"]/;
const GENERATED_START = 'AUTO-GENERATED-START: LOCALE_DELIVERY_MANIFEST';
const GENERATED_END = 'AUTO-GENERATED-END: LOCALE_DELIVERY_MANIFEST';

/** @type {string[]} */
const problems = [];
/** @type {string | null} */
let manifestVersion = null;

for (const file of fs
  .readdirSync(srcDir)
  .filter(f => f.endsWith('.js'))
  .sort()) {
  const lines = fs.readFileSync(path.join(srcDir, file), 'utf8').split('\n');
  let inGenerated = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.includes(GENERATED_START)) inGenerated = true;
    if (line.includes(GENERATED_END)) inGenerated = false;
    const trimmed = line.trim();
    if (trimmed.startsWith('//') || trimmed.startsWith('*') || trimmed.startsWith('/*')) continue;
    const match = VERSION_RE.exec(line);
    if (!match) continue;
    if (inGenerated && file === 'i18n.js') {
      manifestVersion = match[1];
      continue;
    }
    problems.push(
      `  ${file}:${i + 1}  hardcoded "${match[1]}" — use YouTubeUtils.getScriptVersion()  →  ${trimmed}`
    );
  }
}

if (manifestVersion !== canonicalVersion) {
  problems.push(
    `  i18n.js  LOCALE_DELIVERY_MANIFEST.version = ${manifestVersion ?? '(not found)'}  →  expected "${canonicalVersion}" (run npm run sync:locales)`
  );
}

if (problems.length > 0) {
  console.error(`\n❌ Version drift (package.json is "${canonicalVersion}"):\n`);
  for (const p of problems) console.error(p);
  process.exit(1);
}

console.log(
  `✅ Version consistency check passed: no hardcoded versions in src; manifest = "${canonicalVersion}"`
);
